<script setup lang="ts">
import { Braces, RefreshCw, Square, UserRound } from "@lucide/vue"
import { computed } from "vue"
import type { Job, StructuredDocument } from "../types"
import OutlineTree from "./OutlineTree.vue"

const props = defineProps<{ value: StructuredDocument | null; draft: StructuredDocument | null; job: Job | null; hasMarkdown: boolean; blocked: boolean }>()
defineEmits<{ generate: []; stop: []; openMarkdown: [] }>()
const active = computed(() => props.job && ["queued", "waiting_for_model", "running"].includes(props.job.state))
const result = computed(() => props.draft || props.value)
const progress = computed(() => props.job?.total_units ? Math.round(props.job.completed_units / props.job.total_units * 100) : 0)
const labels: Record<string, string> = { extracting_title: "Extracting title", extracting_authors: "Extracting authors", extracting_abstract: "Extracting abstract", extracting_keywords: "Extracting keywords", building_outline: "Building outline", preparing: "Preparing" }
</script>

<template>
  <section class="structure-tab">
    <header><div><p>STRUCTURED INFORMATION</p><h2>Document Details</h2></div><div><button v-if="active" class="stop" @click="$emit('stop')"><Square :size="12" fill="currentColor" />Stop</button><button v-else :disabled="blocked || !hasMarkdown" @click="$emit('generate')"><RefreshCw v-if="value" :size="15" /><Braces v-else :size="16" />{{ value ? "Regenerate" : "Generate Structure" }}</button></div></header>
    <div v-if="!hasMarkdown" class="requirement"><Braces :size="22" /><div><strong>Generate Markdown first</strong><p>Structured information is derived from the completed Markdown document.</p></div><button @click="$emit('openMarkdown')">Open Markdown</button></div>
    <div v-if="active" class="progress"><div><span>{{ labels[job?.stage ?? ""] ?? "Processing document" }} · {{ job?.completed_units ?? 0 }} of {{ job?.total_units || 5 }}</span><strong>{{ progress }}%</strong></div><span><i :style="{ width: `${progress}%` }"></i></span></div>
    <div v-if="result" class="details">
      <div v-if="result.stale" class="stale"><strong>Outdated</strong> — regenerate from the latest Markdown.</div>
      <article><small>TITLE</small><h3>{{ result.title || "Not found" }}</h3></article>
      <article><small>AUTHORS</small><div v-if="result.authors.length" class="authors"><section v-for="author in result.authors" :key="author.name"><UserRound :size="17" /><div><strong>{{ author.name }}</strong><span v-for="affiliation in author.affiliations" :key="affiliation">{{ affiliation }}</span><a v-for="email in author.emails" :key="email" :href="`mailto:${email}`">{{ email }}</a><span v-for="identifier in author.identifiers" :key="identifier">ORCID {{ identifier }}</span></div></section></div><p v-else>Not found</p></article>
      <article><small>AFFILIATIONS</small><ul v-if="result.affiliations.length"><li v-for="item in result.affiliations" :key="item">{{ item }}</li></ul><p v-else>Not found</p></article>
      <article><small>ABSTRACT</small><p class="abstract">{{ result.abstract || "Not found" }}</p></article>
      <article><small>KEYWORDS</small><div v-if="result.keywords.length" class="keywords"><span v-for="item in result.keywords" :key="item">{{ item }}</span></div><p v-else>Not found</p></article>
      <article><small>OUTLINE</small><OutlineTree v-if="result.outline.length" :items="result.outline" /><p v-else>Not found</p></article>
      <aside v-if="result.warnings.length"><strong>Review suggested</strong><p v-for="warning in result.warnings" :key="warning">{{ warning }}</p></aside>
    </div>
    <div v-else-if="hasMarkdown && !active" class="empty"><Braces :size="42" /><h3>No structured information yet</h3><p>Extract metadata and a reliable outline from the completed Markdown.</p></div>
  </section>
</template>

<style scoped>
